from itertools import product
from typing import Callable, Sequence, Tuple, List
import numpy as np

Config = Tuple[int, ...]

def nontrivial_bipartitions(n: int) -> List[Tuple[int, ...]]:
    out, seen = [], set()
    for S in product([0, 1], repeat=n):
        s = tuple(i for i in range(n) if S[i])
        if 1 <= len(s) <= n - 1 and s not in seen:
            seen.add(s); out.append(s)
    return out

def schmidt_rank_at(psi, n, d, S) -> int:
    Sl = sorted(S); Sc = sorted(set(range(n)) - set(Sl))
    rows = list(product(range(d), repeat=len(Sl)))
    cols = list(product(range(d), repeat=len(Sc)))
    M = np.zeros((len(rows), len(cols)), dtype=complex)
    for i, a in enumerate(rows):
        for j, b in enumerate(cols):
            full = [0]*n
            for s, v in zip(Sl, a): full[s] = v
            for s, v in zip(Sc, b): full[s] = v
            M[i, j] = psi(tuple(full))
    s = np.linalg.svd(M, compute_uv=False)
    return int(np.sum(s > 1e-9 * max(1.0, s[0]))) if s.size else 0

def phi_mip(psi, n, d) -> int:
    return min(max(schmidt_rank_at(psi, n, d, S) - 1, 0)
               for S in nontrivial_bipartitions(n))

def ghz(x: Config) -> complex:
    return 1/np.sqrt(2) if all(v==0 for v in x) or all(v==1 for v in x) else 0.0

# GHZ: every cut has rank 2, so Phi = 1 (minimally but genuinely integrated).
print("GHZ Phi:", phi_mip(ghz, 3, 2))
